 function routeHash(target){const query=new URLSearchParams();if(['period','period-artists','period-artworks','period-lessons'].includes(target))query.set('period',activePeriodId.value);if(['artist','artist-artworks'].includes(target)){query.set('artist',activeArtistId.value);query.set('period',activePeriodId.value);if(target==='artist')query.set('from',artistReturn.value)}if(target==='artwork'){query.set('artwork',activeArtworkId.value);query.set('from',artworkReturn.value)}if(target==='lesson'){query.set('lesson',activeLessonId.value);query.set('from',lessonReturn.value)}const suffix=query.toString();return`#${target}${suffix?`?${suffix}`:''}`}
 function applyRoute(hash=location.hash,{restore=true}={}){const [name='timeline',queryText='']=hash.replace(/^#/,'').split('?'),target=routePages.has(name)?name:'timeline',query=new URLSearchParams(queryText);if(query.get('period')&&by(periods,query.get('period')))activePeriodId.value=query.get('period');if(query.get('artist')&&by(artists.value,query.get('artist')))activeArtistId.value=query.get('artist');if(query.get('artwork')&&by(artworks.value,query.get('artwork')))activeArtworkId.value=query.get('artwork');if(query.get('lesson')&&by(allLessons.value,query.get('lesson')))activeLessonId.value=query.get('lesson');if(query.get('from')){if(target==='artwork')artworkReturn.value=query.get('from');if(target==='artist')artistReturn.value=query.get('from');if(target==='lesson')lessonReturn.value=query.get('from')}if(target==='lesson')ensureProgress(activeLesson.value,false);page.value=target;nextTick(()=>scrollRoot.value?.scrollTo({top:restore?(history.state?.scrollY||0):0,left:0,behavior:'auto'}))}
 function handlePopState(){applyRoute(location.hash)}
 onMounted(()=>{document.addEventListener('keydown',handleDocumentKeydown);document.addEventListener('pointerdown',handleDocumentPointer);document.addEventListener('error',handleImageError,true);document.addEventListener('load',handleImageLoad,true);window.addEventListener('popstate',handlePopState);applyRoute(location.hash,{restore:false});history.replaceState({...(history.state||{}),scrollY:0,from:page.value==='artwork'?artworkReturn.value:page.value==='artist'?artistReturn.value:page.value==='lesson'?lessonReturn.value:''},'',routeHash(page.value))});
