 function updateCollectionFilter(scope,{id,value}){if(scope==='gallery'){if(id==='period')galleryPeriod.value=value;if(id==='artist')galleryArtist.value=value}else if(scope==='colors'){if(id==='family')colorsFamily.value=value;if(id==='period')colorsPeriod.value=value}else if(scope==='period-artworks'){if(id==='artist')periodArtworkArtist.value=value;if(id==='type')periodArtworkType.value=value}else if(scope==='artist-artworks'&&id==='type')artistArtworkType.value=value}
 function resetCollectionFilters(scope){if(scope==='gallery'){galleryPeriod.value='all';galleryArtist.value='all'}else if(scope==='colors'){colorsFamily.value='all';colorsPeriod.value='all'}else if(scope==='period-artworks'){periodArtworkArtist.value='all';periodArtworkType.value='all'}else if(scope==='artist-artworks')artistArtworkType.value='all'}
 function showMore(scope,total){if(scope==='gallery')galleryVisible.value=nextVisibleCount(galleryVisible.value,total);else if(scope==='colors')colorsVisible.value=nextVisibleCount(colorsVisible.value,total);else if(scope==='library')libraryVisible.value=nextVisibleCount(libraryVisible.value,total);else if(scope==='period-artists')periodArtistVisible.value=nextVisibleCount(periodArtistVisible.value,total);else if(scope==='period-artworks')periodArtworkVisible.value=nextVisibleCount(periodArtworkVisible.value,total);else if(scope==='period-lessons')periodLessonVisible.value=nextVisibleCount(periodLessonVisible.value,total);else if(scope==='artist-artworks')artistArtworkVisible.value=nextVisibleCount(artistArtworkVisible.value,total)}
