	 async function runDiscovery(){if(discoveryProgress.value)return;const period=activePeriod.value;discoveryError.value='';discoveryProgress.value={phase:'plan',done:0,total:1,message:'Подготовка исследования…',artists:periodLocalArtists.value.length,artworks:periodLocalArtworks.value.length};try{const result=await discoverEpoch({period,db,existingArtistNames:periodArtists.value.map(item=>item.name),existingArtworkKeys:officialMuseumKeys,persist:()=>replaceArchive(clone(db)),onProgress:value=>{discoveryProgress.value=value}});notify(result.addedCount?`Добавлено произведений: ${result.addedCount}`:'Новых подтверждённых произведений не найдено')}catch(error){discoveryError.value=error.message||'Исследование приостановлено. Его можно продолжить позже.'}finally{discoveryProgress.value=null}}
