	 function epochLessonArtworkIds(){if(epochLessonMode.value==='artwork')return epochLessonArtwork.value?[epochLessonArtwork.value]:[];if(epochLessonMode.value==='artist')return periodArtworks.value.filter(item=>item.artistId===epochLessonArtist.value).slice(0,6).map(item=>item.id);if(epochLessonMode.value==='compare')return periodArtworks.value.filter(item=>[epochLessonArtist.value,epochLessonArtistSecond.value].includes(item.artistId)).slice(0,6).map(item=>item.id);return periodArtworks.value.slice(0,6).map(item=>item.id)}
	 function storeGeneratedLesson(lesson,origin='library'){db.personalLessons=[...db.personalLessons.filter(item=>item.id!==lesson.id),lesson];if(!db.createdPersonalLessonIds.includes(lesson.id))db.createdPersonalLessonIds.push(lesson.id);ensureProgress(lesson,false);activeLessonId.value=lesson.id;lessonReturn.value=origin;notify('Персональный урок создан и сохранён.');go('lesson')}
	 async function createEpochLesson(){if(epochLessonLoading.value)return;epochLessonError.value='';if(epochLessonMode.value==='compare'&&(!epochLessonArtist.value||!epochLessonArtistSecond.value||epochLessonArtist.value===epochLessonArtistSecond.value)){epochLessonError.value='Для сравнения выбери двух разных художников.';return}if(epochLessonMode.value==='artist'&&!epochLessonArtist.value){epochLessonError.value='Выбери художника или мастера.';return}if(epochLessonMode.value==='artwork'&&!epochLessonArtwork.value){epochLessonError.value='Выбери произведение.';return}epochLessonLoading.value=true;try{const request=compactEpochLessonPayload({topicId:activePeriod.value.id,mode:epochLessonMode.value,artistId:epochLessonArtist.value,artworkIds:epochLessonArtworkIds(),level:epochLessonLevel.value,style:epochLessonStyle.value,localArtworks:periodLocalArtworks.value,localQuestions:db.localQuestions}),response=await fetch('/.netlify/functions/ai-lesson',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(request)}),body=await response.json().catch(()=>null);if(!response.ok)throw Error(body?.error||'Сервис Gemini недоступен.');if(!body?.lesson?.id||!Array.isArray(body.lesson.blocks))throw Error('Gemini вернул урок в неверном формате.');epochLessonOpen.value=false;storeGeneratedLesson(body.lesson,'period')}catch(error){epochLessonError.value=error.message||'Не удалось создать урок по эпохе.'}finally{epochLessonLoading.value=false}}
 function progressFor(lessonId){return db.lessonProgress.find(item=>item.lessonId===lessonId)||null}
 function ensureProgress(lesson,restart=false){let progress=progressFor(lesson.id);if(!progress){progress={lessonId:lesson.id,source:lesson.source,status:'new',currentBlock:0,completedBlocks:[],startedAt:'',updatedAt:'',completedAt:'',answers:{},reflection:''};db.lessonProgress.push(progress)}if(restart){Object.assign(progress,{status:'in-progress',currentBlock:0,completedBlocks:[],startedAt:iso(),updatedAt:iso(),completedAt:'',answers:{},reflection:''})}else if(progress.status==='new'){Object.assign(progress,{status:'in-progress',startedAt:iso(),updatedAt:iso()})}return progress}
 function openLesson(id,origin='library',restart=false){const lesson=by(allLessons.value,id);if(!lesson)return;activeLessonId.value=id;lessonReturn.value=origin;ensureProgress(lesson,restart);lessonAnswer.value=null;go('lesson')}
 function lessonStatus(id){return progressFor(id)?.status||'new'}
 function lessonProgressPercent(lesson){const progress=progressFor(lesson.id);return progress?Math.round(progress.completedBlocks.length/lesson.blocks.length*100):0}
 function periodStats(period){return periodStatsMap.value.get(period.id)||{artists:0,artworks:0,lessons:0,completedLessons:0,progressPercent:null}}
 function periodProgress(period){return periodStats(period).progressPercent}
 function answerLessonQuestion(id){const progress=lessonProgressRecord.value,question=lessonQuestion.value,block=currentLessonBlock.value;if(!progress||!question||progress.answers[block.id])return;progress.answers[block.id]={selectedId:id,correct:id===question.correct,answeredAt:iso()};lessonAnswer.value=id;progress.updatedAt=iso()}
 function updateLessonReflection(value){const progress=lessonProgressRecord.value;if(progress){progress.reflection=value.slice(0,1200);progress.updatedAt=iso()}}
 function nextLessonBlock(){const lesson=activeLesson.value,progress=lessonProgressRecord.value,block=currentLessonBlock.value;if(!progress||!block)return;if(block.type==='question'&&!progress.answers[block.id])return;if(!progress.completedBlocks.includes(block.id))progress.completedBlocks.push(block.id);progress.updatedAt=iso();if(progress.currentBlock<lesson.blocks.length-1){progress.currentBlock+=1;lessonAnswer.value=null;resetScroll(true)}else{progress.status='completed';progress.completedAt=iso();notify('Урок завершён и сохранён в истории.');go(['period','period-lessons'].includes(lessonReturn.value)?lessonReturn.value:'library')}}
 function previousLessonBlock(){const progress=lessonProgressRecord.value;if(progress&&progress.currentBlock>0){progress.currentBlock-=1;lessonAnswer.value=null;progress.updatedAt=iso();resetScroll(true)}}
