	 function openPractice(scopeType='all',scopeId='',origin=page.value){practiceScopeType.value=['period','artist'].includes(scopeType)?scopeType:'all';practiceScopeId.value=practiceScopeType.value==='all'?'':scopeId;practiceReturn.value=['period','artist'].includes(origin)?origin:'practice';selectedPracticeMode.value='recognize';go('practice')}
