	 function artworkCountLabel(count){const last=count%10,lastTwo=count%100,suffix=lastTwo>=11&&lastTwo<=14?'произведений':last===1?'произведение':last>=2&&last<=4?'произведения':'произведений';return`${count} ${suffix}`}
	 function startPractice(setId,{kind='standard',questionIds=null,embeddedQuestions=[],scopeType='',scopeId='',scopeLabel='',mode=''}={}){const set=by(practiceSets,setId),ids=questionIds||set?.questionIds,bank=[...questionBank.value,...embeddedQuestions];if(!ids?.length){notify('Нет проверенных вопросов для повторения.');return}const session=createPracticeSession({practiceSetId:setId||'review-errors',questionIds:ids,questionBank:bank,embeddedQuestions,kind,scopeType,scopeId,scopeLabel,mode,seed:seed()});db.practiceSessions.push(session);activeSessionId.value=session.id;go('practice-session')}
	 function startSelectedPractice(){const generated=buildPracticeMode({mode:selectedPracticeMode.value,artworks:artworks.value,questionBank:questionBank.value,scopeType:practiceScopeType.value,scopeId:practiceScopeId.value,seed:seed()});if(!generated.available){notify(generated.reason);return}startPractice(`custom-${selectedPracticeMode.value}`,{questionIds:generated.questions.map(item=>item.id),embeddedQuestions:generated.questions,scopeType:practiceScopeType.value,scopeId:practiceScopeId.value,scopeLabel:practiceScopeLabel.value,mode:selectedPracticeMode.value})}
