 function isFavorite(id){return db.favorites.some(item=>item.artworkId===id)}
 function toggleFavorite(id){db.favorites=isFavorite(id)?db.favorites.filter(item=>item.artworkId!==id):[...db.favorites,{artworkId:id,createdAt:iso()}];notify(isFavorite(id)?'Добавлено в личную галерею':'Удалено из галереи')}
 function hasSavedColor(id,index){return db.colors.some(item=>item.id===`${id}:${index}`)}
 function toggleSavedColor(artwork,index){const id=`${artwork.id}:${index}`;if(hasSavedColor(artwork.id,index)){db.colors=db.colors.filter(item=>item.id!==id);for(const palette of db.emotionPalettes)palette.colorIds=palette.colorIds.filter(colorId=>colorId!==id);notify('Цвет убран')}else{const savedAt=iso(),savedOrder=(db.settings.colorSaveSequence||0)+1;db.settings.colorSaveSequence=savedOrder;db.colors.push({id,artworkId:artwork.id,index,hex:artwork.palette[index],savedAt,createdAt:savedAt,savedOrder});notify('Цвет сохранён')}}
 function openArtworkViewer(){artworkViewerOpen.value=true}
 function closeArtworkViewer(){artworkViewerOpen.value=false}
 function savePickedColor(selection){const artwork=activeArtwork.value,hex=String(selection?.hex||'').toUpperCase();if(!/^#[0-9A-F]{6}$/.test(hex))return;if(db.colors.some(color=>color.source==='user-picked'&&color.artworkId===artwork.id&&color.hex===hex)){notify('Этот оттенок уже сохранён для картины');return}const savedAt=iso(),savedOrder=(db.settings.colorSaveSequence||0)+1,index=db.colors.filter(color=>color.artworkId===artwork.id&&color.source==='user-picked').reduce((highest,color)=>Math.max(highest,color.index),-1)+1;db.settings.colorSaveSequence=savedOrder;db.colors.push({id:`picked-${Date.now().toString(36)}-${Math.random().toString(36).slice(2,8)}`,artworkId:artwork.id,index,hex,source:'user-picked',x:selection.x,y:selection.y,savedAt,createdAt:savedAt,savedOrder});lastDeletedColor.value=null;notify(`Оттенок ${hex} сохранён`)}
 function removeUserColor(color){if(color?.source!=='user-picked')return;const stored=db.colors.find(item=>item.id===color.id);if(!stored)return;lastDeletedColor.value={color:clone(stored),emotionIds:db.emotionPalettes.filter(palette=>palette.colorIds.includes(color.id)).map(palette=>palette.emotionId)};db.colors=db.colors.filter(item=>item.id!==color.id);for(const palette of db.emotionPalettes)palette.colorIds=palette.colorIds.filter(colorId=>colorId!==color.id);clearTimeout(undoTimer);undoTimer=setTimeout(()=>lastDeletedColor.value=null,5000);notify('Мой оттенок удалён')}
 function undoDeletedColor(){if(!lastDeletedColor.value)return;const deleted=lastDeletedColor.value;db.colors.push(deleted.color);db.settings.colorSaveSequence=Math.max(db.settings.colorSaveSequence,deleted.color.savedOrder||0);for(const emotionId of deleted.emotionIds){const palette=db.emotionPalettes.find(item=>item.emotionId===emotionId);if(palette&&!palette.colorIds.includes(deleted.color.id))palette.colorIds.push(deleted.color.id)}lastDeletedColor.value=null;clearTimeout(undoTimer);notify('Оттенок восстановлен')}
 function updateReflection(patch){const current=db.reflections.find(item=>item.artworkId===activeArtwork.value.id);if(current)Object.assign(current,patch,{updatedAt:iso()});else db.reflections.push({...activeReflection.value,...patch,updatedAt:iso()})}
