 function toggleMoodColor(colorId){let palette=db.emotionPalettes.find(item=>item.emotionId===moodOpen.value);if(!palette){palette={emotionId:moodOpen.value,colorIds:[],seed:seed()};db.emotionPalettes.push(palette)}palette.colorIds=palette.colorIds.includes(colorId)?palette.colorIds.filter(id=>id!==colorId):[...palette.colorIds,colorId]}
 function shuffleEmotions(){db.settings.emotionShuffleSeed=seed();for(const palette of db.emotionPalettes)palette.seed=seed()}
 function setInterfaceColorMode(mode){if(['automatic','manual'].includes(mode))db.settings.interfaceColorMode=mode}
 function setManualInterfaceColor(index,value){const hex=String(value||'').trim().toUpperCase();if(!Number.isInteger(index)||index<0||index>2||!/^#[0-9A-F]{6}$/.test(hex)){notify('Используй HEX в формате #A1B2C3');return}const palette=[...db.settings.manualInterfacePalette];palette[index]=hex;db.settings.manualInterfacePalette=palette}
 function globalIconStyle(key){return iconPaletteStyle(activeIconColors.value,key)}
