 function emotionIconStyle(id){const palette=emotionPalette(id),colors=palette.colorIds.map(colorId=>db.colors.find(color=>color.id===colorId)?.hex).filter(Boolean);if(!colors.length)return iconPaletteStyle([],`emotion:${id}`);const start=(palette.seed+db.settings.emotionShuffleSeed)%colors.length,ordered=colors.map((_,index)=>colors[(start+index)%colors.length]);return iconPaletteStyle(ordered,`emotion:${id}:${palette.seed}:${db.settings.emotionShuffleSeed}`)}

 async function generateAI(){aiLoading.value=true;aiError.value='';try{const response=await fetch('/.netlify/functions/ai-lesson',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({topicId:aiTopic.value,level:aiLevel.value,style:aiStyle.value})});const body=await response.json().catch(()=>null);if(!response.ok)throw Error(body?.error||'Сервис Gemini недоступен.');const lesson=body?.lesson;if(!lesson?.id||!Array.isArray(lesson.blocks))throw Error('Gemini вернул урок в неверном формате.');storeGeneratedLesson(lesson,'library')}catch(error){aiError.value=error.message||'Не удалось создать урок.'}finally{aiLoading.value=false}}

